{
  "conversations": [
    {
      "title": "Describe my symptoms",
      "lines": [
        { "speaker": "you", "text": "My stomach hurts." },
        { "speaker": "you", "text": "I have terrible diarrhea.", "or": true },
        { "speaker": "partner", "text": "How long has it hurt?" },
        { "speaker": "you", "text": "Since this morning." },
        { "speaker": "you", "text": "Since yesterday.", "or": true }
      ]
    },
    {
      "title": "Ask about medication",
      "lines": [
        { "speaker": "you", "text": "What do you suggest for stomach pain?" },
        { "speaker": "partner", "text": "Take these pills after meals." },
        { "speaker": "you", "text": "How often should I take them?" },
        { "speaker": "partner", "text": "Three times a day." },
        { "speaker": "you", "text": "Thank you." }
      ]
    },
    {
      "title": "Explain allergies",
      "lines": [
        { "speaker": "you", "text": "Does this medicine have aspirin?" },
        { "speaker": "partner", "text": "Yes, it does." },
        { "speaker": "you", "text": "I'm allergic to aspirin." },
        { "speaker": "partner", "text": "Let me find something else for you." },
        { "speaker": "you", "text": "Thank you." }
      ]
    }
  ]
}
